        }
    }
}
foreach ($__MtPackImport in $__MtPackImports) { Set-Item -Path "function:script:$($__MtPackImport.Name)" -Value $__MtPackImport.ScriptBlock }
foreach ($__MtPackFile in $__MtPackFiles) { . $__MtPackFile }
