    $script:__MtPackModules[$key] = [pscustomobject]@{ Module = $module; Pack = $Pack }
    if (-not $script:__MtPackModuleOwner) { $script:__MtPackModuleOwner = @{} }
    $script:__MtPackModuleOwner[$name] = $Pack
    $module
}

