# Unit tests of the enrollment, webhook and compliance benchmark checks (MP.JAMF.1012 to 1017, 1025 and 2001).
Describe 'Jamf Pro pack: enrollment, webhooks and compliance benchmarks' {
    BeforeAll {
        . "$PSScriptRoot/Fixture.ps1"
        Import-JamfSpecMaester

        function New-JamfSpecPrestage {
            param([string] $Name = 'Corp Macs', [hashtable] $Set = @{})
            $p = @{ id = [guid]::NewGuid().ToString(); displayName = $Name; mandatory = $true; mdmRemovable = $false; requireAuthentication = $true; supervised = $true; defaultPrestage = $false }
            foreach ($k in $Set.Keys) { $p[$k] = $Set[$k] }
            $p
        }

        function New-JamfSpecEa {
            param([string] $Name, [object[]] $Values = @())
            @{ definitionId = '1'; name = $Name; values = $Values; dataType = 'STRING'; enabled = $true; multiValue = $false }
        }

        function New-JamfSpecRule {
            param([string] $Id = 'audit_acls_files_configure', [int] $Passed = 10, [int] $Failed = 0, [int] $Unknown = 0, [double] $Percent = -1, [string] $Number)
            $devices = $Passed + $Failed + $Unknown
            if ($Percent -lt 0) { $Percent = if ($devices) { 100 * $Passed / $devices } else { 0 } }
            $r = @{ ruleId = $Id; ruleTitle = "Rule $Id"; sectionName = 'Auditing'; passed = $Passed; failed = $Failed; unknown = $Unknown; passPercentage = $Percent; numberOfDevices = $devices }
            if ($Number) { $r.ruleNumber = $Number }
            $r
        }

        $script:Webhook = {
            param([int] $Id, [string] $Name, [string] $Url, [string] $Auth = 'BASIC', [bool] $Enabled = $true)
            @{ webhook = @{ id = $Id; name = $Name; enabled = $Enabled; url = $Url; content_type = 'application/json'; event = 'ComputerAdded'; authentication_type = $Auth; username = 'hook'; password = 'REDACTED' } }
        }
    }

    Context 'MP.JAMF.1012 user-initiated enrollment' {
        It 'passes when user-initiated enrollment of Macs is off' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1012 -Cache @{ 'api/v4/enrollment' = @{ macOsEnterpriseEnrollmentEnabled = $false } }).Result | Should -Be 'Passed'
        }

        It 'asks for review with the groups that may enroll when it is on' {
            $cache = @{
                'api/v4/enrollment'                       = @{ macOsEnterpriseEnrollmentEnabled = $true }
                'paged:api/v3/enrollment/access-groups?' = @(@{ id = '1'; groupId = '10'; ldapServerId = '1'; name = 'Mac Admins'; enterpriseEnrollmentEnabled = $true; personalEnrollmentEnabled = $false })
            }
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1012 -Cache $cache
            $row.Result | Should -Be 'Investigate'
            $row.ResultDetail.TestResult | Should -Match 'Mac Admins'
        }

        It 'asks for review when no group limits it' {
            $cache = @{ 'api/v4/enrollment' = @{ macOsEnterpriseEnrollmentEnabled = $true }; 'paged:api/v3/enrollment/access-groups?' = @() }
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1012 -Cache $cache
            $row.Result | Should -Be 'Investigate'
            $row.ResultDetail.TestResult | Should -Match 'No directory group'
        }
    }

    Context 'MP.JAMF.1013 computer PreStage MDM profile' {
        It 'passes when every PreStage keeps the MDM profile' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1013 -Cache @{ 'paged:api/v3/computer-prestages?' = @((New-JamfSpecPrestage)) }).Result | Should -Be 'Passed'
        }

        It 'fails and lists a PreStage whose profile is removable or not mandatory' {
            $prestages = @((New-JamfSpecPrestage), (New-JamfSpecPrestage -Name 'Lab' -Set @{ mdmRemovable = $true }), (New-JamfSpecPrestage -Name 'Loaner' -Set @{ mandatory = $false }))
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1013 -Cache @{ 'paged:api/v3/computer-prestages?' = $prestages }
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'Lab'
            $row.ResultDetail.TestResult | Should -Match 'Loaner'
            $row.ResultDetail.TestResult | Should -Not -Match 'Corp Macs'
        }

        It 'is skipped when there is no PreStage' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1013 -Cache @{ 'paged:api/v3/computer-prestages?' = @() }).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1014 computer PreStage authentication' {
        It 'passes when every PreStage requires authentication' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1014 -Cache @{ 'paged:api/v3/computer-prestages?' = @((New-JamfSpecPrestage)) }).Result | Should -Be 'Passed'
        }

        It 'fails when a PreStage does not require authentication' {
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1014 -Cache @{ 'paged:api/v3/computer-prestages?' = @((New-JamfSpecPrestage -Name 'Open' -Set @{ requireAuthentication = $false })) }
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'Open'
        }

        It 'is skipped when there is no PreStage' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1014 -Cache @{ 'paged:api/v3/computer-prestages?' = @() }).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1015 mobile device PreStage' {
        It 'passes when every PreStage supervises and keeps the profile' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1015 -Cache @{ 'paged:api/v3/mobile-device-prestages?' = @((New-JamfSpecPrestage -Name 'iPads')) }).Result | Should -Be 'Passed'
        }

        It 'fails when a PreStage does not supervise or lets the profile be removed' {
            $prestages = @((New-JamfSpecPrestage -Name 'BYOD' -Set @{ supervised = $false }), (New-JamfSpecPrestage -Name 'Kiosk' -Set @{ mdmRemovable = $true }))
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1015 -Cache @{ 'paged:api/v3/mobile-device-prestages?' = $prestages }
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'BYOD'
            $row.ResultDetail.TestResult | Should -Match 'Kiosk'
        }

        It 'is skipped when there is no PreStage' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1015 -Cache @{ 'paged:api/v3/mobile-device-prestages?' = @() }).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1016 Automated Device Enrollment tokens' {
        BeforeAll {
            $script:Token = { param([string] $Name, [int] $Days) @{ id = '1'; name = $Name; orgName = 'Contoso'; tokenExpirationDate = [datetime]::UtcNow.AddDays($Days).ToString('yyyy-MM-dd') } }
        }

        It 'passes when no token expires soon' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1016 -Cache @{ 'paged:api/v1/device-enrollments?' = @((& $script:Token 'ABM' 200)) }).Result | Should -Be 'Passed'
        }

        It 'fails when a token expires within the warning period' {
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1016 -Cache @{ 'paged:api/v1/device-enrollments?' = @((& $script:Token 'ABM' 200), (& $script:Token 'ASM' 10)) }
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'ASM'
        }

        It 'fails when a token has expired' {
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1016 -Cache @{ 'paged:api/v1/device-enrollments?' = @((& $script:Token 'Old' -5)) }
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'Expired'
        }

        It 'takes the warning period from the WarningDays parameter' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1016 -Cache @{ 'paged:api/v1/device-enrollments?' = @((& $script:Token 'ASM' 10)) } -Parameter @{ WarningDays = 7 }).Result | Should -Be 'Passed'
        }

        It 'is skipped when there is no instance' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1016 -Cache @{ 'paged:api/v1/device-enrollments?' = @() }).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1017 webhooks' {
        It 'passes when enabled webhooks use HTTPS and authentication, ignoring disabled ones' {
            $cache = @{
                'JSSResource/webhooks'      = @{ webhooks = @(@{ id = 1; name = 'SIEM' }, @{ id = 2; name = 'Old' }) }
                'JSSResource/webhooks/id/1' = & $script:Webhook 1 'SIEM' 'https://siem.contoso.com/hook'
                'JSSResource/webhooks/id/2' = & $script:Webhook 2 'Old' 'http://old.contoso.com/hook' 'NONE' $false
            }
            (Invoke-JamfSpecTest -Id MP.JAMF.1017 -Cache $cache).Result | Should -Be 'Passed'
        }

        It 'fails on plain HTTP or no authentication, without showing the password or the path' {
            $cache = @{
                'JSSResource/webhooks'      = @{ webhooks = @(@{ id = 1; name = 'Plain' }, @{ id = 2; name = 'Anonymous' }) }
                'JSSResource/webhooks/id/1' = & $script:Webhook 1 'Plain' 'http://hooks.contoso.com/secret-token-123'
                'JSSResource/webhooks/id/2' = & $script:Webhook 2 'Anonymous' 'https://hooks.contoso.com/x' 'NONE'
            }
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1017 -Cache $cache
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'Plain'
            $row.ResultDetail.TestResult | Should -Match 'Anonymous'
            $row.ResultDetail.TestResult | Should -Not -Match 'REDACTED'
            $row.ResultDetail.TestResult | Should -Not -Match 'secret-token-123'
        }

        It 'leaves out the webhooks named in ExcludedWebhook' {
            $cache = @{
                'JSSResource/webhooks'      = @{ webhooks = @(@{ id = 1; name = 'SIEM' }, @{ id = 2; name = 'Local' }) }
                'JSSResource/webhooks/id/1' = & $script:Webhook 1 'SIEM' 'https://siem.contoso.com/hook'
                'JSSResource/webhooks/id/2' = & $script:Webhook 2 'Local' 'http://localhost:8080/hook' 'NONE'
            }
            (Invoke-JamfSpecTest -Id MP.JAMF.1017 -Cache $cache -Parameter @{ ExcludedWebhook = @('Local') }).Result | Should -Be 'Passed'
        }

        It 'is skipped when there is no webhook' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1017 -Cache @{ 'JSSResource/webhooks' = @{ webhooks = @() } }).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1025 mSCP compliance script' {
        It 'passes when enough reporting Macs have no failed rule, and leaves out Macs that do not report' {
            $macs = @(1..9 | ForEach-Object { New-JamfSpecMac -Name "Mac-$_" -ExtensionAttributes @((New-JamfSpecEa 'Compliance - Failed Results Count' @('0'))) }) +
                (New-JamfSpecMac -Name 'Drifted' -ExtensionAttributes @((New-JamfSpecEa 'Compliance - Failed Results Count' @('4')))) +
                (New-JamfSpecMac -Name 'Silent' -ExtensionAttributes @((New-JamfSpecEa 'Compliance - Failed Results Count' @()), (New-JamfSpecEa 'Compliance - Failed Result List' @()))) +
                (New-JamfSpecMac -Name 'Plain')
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1025 -Cache @{ (Get-JamfSpecQuery Computers) = $macs }
            $row.Result | Should -Be 'Passed'
            $row.ResultDetail.TestResult | Should -Match '9 of 10'
            $row.ResultDetail.TestResult | Should -Match 'Drifted'
        }

        It 'fails below the minimum share, reading a benchmark failed result list' {
            $macs = @(
                (New-JamfSpecMac -Name 'Clean' -ExtensionAttributes @((New-JamfSpecEa 'CIS Level 1 - Failed Result List' @('')))),
                (New-JamfSpecMac -Name 'Drifted' -ExtensionAttributes @((New-JamfSpecEa 'CIS Level 1 - Failed Result List' @("os_gatekeeper_enable`nos_sip_enable"))))
            )
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1025 -Cache @{ (Get-JamfSpecQuery Computers) = $macs }
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'Drifted \| 2'
        }

        It 'takes the share from the MinimumPercent parameter' {
            $macs = @(
                (New-JamfSpecMac -Name 'Clean' -ExtensionAttributes @((New-JamfSpecEa 'Compliance - Failed Results Count' @('0')))),
                (New-JamfSpecMac -Name 'Drifted' -ExtensionAttributes @((New-JamfSpecEa 'Compliance - Failed Results Count' @('1'))))
            )
            (Invoke-JamfSpecTest -Id MP.JAMF.1025 -Cache @{ (Get-JamfSpecQuery Computers) = $macs } -Parameter @{ MinimumPercent = 50 }).Result | Should -Be 'Passed'
        }

        It 'is skipped with how to deploy the script when no Mac reports' {
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1025 -Cache @{ (Get-JamfSpecQuery Computers) = @((New-JamfSpecMac)) }
            $row.Result | Should -Be 'Skipped'
            $row.ResultDetail.SkippedReason | Should -Match 'Compliance Editor'
        }
    }

    Context 'MP.JAMF.2001 Compliance Benchmarks' {
        BeforeAll {
            $script:Platform = {
                param([object[]] $Rules, [string] $Title = 'CIS Level 1 (macOS 26)')
                @{
                    'compliance-benchmarks/v1/benchmarks'                             = @{ benchmarks = @(@{ id = 'b1'; title = $Title; syncState = 'SYNCED' }) }
                    'compliance-benchmarks/v1/benchmarks/b1/rules?page=0&page-size=500' = @{ totalCount = $Rules.Count; results = $Rules }
                }
            }
        }

        It 'gives one row per rule, mapped to mSCP when the framework knows the rule' {
            $rules = @((New-JamfSpecRule -Id 'audit_acls_files_configure' -Number '3.5'), (New-JamfSpecRule -Id 'custom_rule_unknown' -Passed 5 -Failed 5))
            $rows = Invoke-JamfSpecTest -Id MP.JAMF.2001 -Platform (& $script:Platform $rules)
            $rows.Count | Should -Be 2
            $known = $rows | Where-Object { $_.Id -like '*audit_acls_files_configure' }
            $known.Id | Should -Be 'MP.JAMF.2001.cis-level-1-macos-26.audit_acls_files_configure'
            $known.Result | Should -Be 'Passed'
            $known.Name | Should -Match '3\.5 Rule audit_acls_files_configure'
            $known.Benchmark.Requirement | Should -Be 'audit_acls_files_configure'
            $known.Fields.Benchmark | Should -Be 'CIS Level 1 (macOS 26)'
            $other = $rows | Where-Object { $_.Id -like '*custom_rule_unknown' }
            $other.Result | Should -Be 'Failed'
            $other.ResultDetail.TestResult | Should -Match '\| 5 \| 5 \| 0 \|'
        }

        It 'reads every page of rules' {
            $platform = @{
                'compliance-benchmarks/v1/benchmarks'                             = @{ benchmarks = @(@{ id = 'b1'; title = 'STIG'; syncState = 'SYNCED' }) }
                'compliance-benchmarks/v1/benchmarks/b1/rules?page=0&page-size=500' = @{ totalCount = 2; results = @((New-JamfSpecRule -Id 'rule_one')) }
                'compliance-benchmarks/v1/benchmarks/b1/rules?page=1&page-size=500' = @{ totalCount = 2; results = @((New-JamfSpecRule -Id 'rule_two')) }
            }
            (Invoke-JamfSpecTest -Id MP.JAMF.2001 -Platform $platform).Count | Should -Be 2
        }

        It 'takes the pass rate from the MinimumPassPercent parameter' {
            $rules = @((New-JamfSpecRule -Id 'rule_one' -Passed 95 -Failed 5))
            (Invoke-JamfSpecTest -Id MP.JAMF.2001 -Platform (& $script:Platform $rules)).Result | Should -Be 'Failed'
            (Invoke-JamfSpecTest -Id MP.JAMF.2001 -Platform (& $script:Platform $rules) -Parameter @{ MinimumPassPercent = 90 }).Result | Should -Be 'Passed'
        }

        It 'asks for review when no device has reported the rule' {
            (Invoke-JamfSpecTest -Id MP.JAMF.2001 -Platform (& $script:Platform @((New-JamfSpecRule -Id 'rule_one' -Passed 0 -Unknown 4)))).Result | Should -Be 'Investigate'
        }

        It 'skips a rule with no device' {
            (Invoke-JamfSpecTest -Id MP.JAMF.2001 -Platform (& $script:Platform @((New-JamfSpecRule -Id 'rule_one' -Passed 0)))).Result | Should -Be 'Skipped'
        }

        It 'is skipped with how to create a benchmark when there is none' {
            $row = Invoke-JamfSpecTest -Id MP.JAMF.2001 -Platform @{ 'compliance-benchmarks/v1/benchmarks' = @{ benchmarks = @() } }
            $row.Result | Should -Be 'Skipped'
            $row.ResultDetail.SkippedReason | Should -Match 'Compliance Benchmarks'
        }
    }
}

